    # Rays from each marker stop at the first nonzero object; markers facing
    # each other on a common row/column connect across the whole gap.
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    marks = [(r,c) for r,row in enumerate(grid) for c,v in enumerate(row) if v == 1]
    for r,c in marks:
        # Shoot in four cardinal directions, coloring empty cells until an obstacle or edge.
        for dr,dc in ((-1,0),(1,0),(0,-1),(0,1)):
            rr,cc=r+dr,c+dc
            while 0 <= rr < h and 0 <= cc < w:
                if grid[rr][cc] == 2:
                    break
                if grid[rr][cc] == 1:
                    out[rr][cc]=1
                else:
                    out[rr][cc]=1
                rr+=dr; cc+=dc
    return out
